import{_ as t,o as a,c as s,a3 as o}from"./chunks/framework.r0uj6mzT.js";const g=JSON.parse('{"title":"Day-to-day operation","description":"","frontmatter":{},"headers":[],"relativePath":"operations/index.md","filePath":"operations/index.md","lastUpdated":1789353831000}'),n={name:"operations/index.md"};function d(i,e,r,c,h,l){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="day-to-day-operation" tabindex="-1">Day-to-day operation <a class="header-anchor" href="#day-to-day-operation" aria-label="Permalink to &quot;Day-to-day operation&quot;">​</a></h1><h2 id="check-the-service" tabindex="-1">Check the service <a class="header-anchor" href="#check-the-service" aria-label="Permalink to &quot;Check the service&quot;">​</a></h2><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-ta_dB" id="tab-6nXMOZr" checked><label data-title="Linux / systemd" for="tab-6nXMOZr">Linux / systemd</label></div><div class="blocks"><div class="language-sh vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz.service</span></span></code></pre></div></div></div><p>The daemon logs to the system journal when run by systemd.</p><p>The daemon writes an info-level <code>daemon started</code> line once its control socket is accepting connections and its worker pools are running, and a <code>daemon stopped</code> line as it exits.</p><h3 id="job-state-lines" tabindex="-1">Job state lines <a class="header-anchor" href="#job-state-lines" aria-label="Permalink to &quot;Job state lines&quot;">​</a></h3><p>Every job state change is written as one <code>worker state</code> line, in the order the daemon recorded it. The line carries these keys:</p><table tabindex="0"><thead><tr><th>Key</th><th>Meaning</th></tr></thead><tbody><tr><td><code>run_id</code></td><td>The run the change belongs to; see <a href="#job-identity">job identity</a></td></tr><tr><td><code>pool</code></td><td>The worker pool: <code>management</code>, <code>transfer</code>, or <code>configuration</code> for a configuration reload</td></tr><tr><td><code>job</code></td><td>The job, for example <code>snapshot:tank/data</code> or <code>remote:tank/data:offsite</code></td></tr><tr><td><code>scope</code></td><td>The dataset the job belongs to</td></tr><tr><td><code>target</code></td><td>The shared resource the job locks, such as a transfer target</td></tr><tr><td><code>state</code></td><td>The state the job moved to; see <a href="#job-states">job states</a></td></tr><tr><td><code>reason</code></td><td>Why, when the state carries one</td></tr><tr><td><code>pending</code></td><td>Jobs waiting in the job&#39;s queue when the change was recorded</td></tr></tbody></table><p>A line also carries the <a href="#job-identity">identity</a> keys its change sets: <code>snapshot</code>, <code>base</code>, <code>mode</code>, <code>destination</code>, <code>marker</code>, <code>destroyed</code> with <code>destroyed_count</code>, and <code>config_generation</code>. A key the change does not set is left out of the line.</p><p>A <code>failed</code> state is logged at error level, <code>blocked</code> and <code>waiting-retry</code> at warning level, and every other state at info level. A successful <code>boomerangz config reload</code> is logged as job <code>config:reload</code> in pool <code>configuration</code>. Transfer progress is not logged.</p><h3 id="discovery-lines" tabindex="-1">Discovery lines <a class="header-anchor" href="#discovery-lines" aria-label="Permalink to &quot;Discovery lines&quot;">​</a></h3><p>Each time the daemon applies a new discovery generation, it writes an info-level <code>discovery complete</code> line with <code>generation</code>, the generation&#39;s number, and <code>datasets</code>, the number of datasets it holds. The line is written once the generation is reflected in <code>status</code>, in order with the job state lines around it. A scan that fails writes a <code>discovery failed</code> line instead, and a configuration reload that republishes the same generation writes no second line.</p><h3 id="gaps-in-the-log" tabindex="-1">Gaps in the log <a class="header-anchor" href="#gaps-in-the-log" aria-label="Permalink to &quot;Gaps in the log&quot;">​</a></h3><p>The log is complete from the moment the daemon starts. If writing to the log falls far enough behind that the daemon has to discard state changes rather than hold them, it writes an error-level <code>status log dropped transitions</code> line in place of each run of discarded changes, with <code>count</code>, the number of changes in the run, job state changes and discovery generations together, and <code>first</code> and <code>last</code>, the times of the earliest and latest of them. The line appears where those changes would have been, and the state changes that follow are written after it. Anything reading the log as a record should treat that line as a gap in it.</p><p>When the daemon stops, the <code>daemon stopped</code> line carries <code>status_backlog_peak</code>: the most state changes any status consumer, including the log, has had waiting to be delivered at once.</p><h2 id="view-status" tabindex="-1">View status <a class="header-anchor" href="#view-status" aria-label="Permalink to &quot;View status&quot;">​</a></h2><p>Show one current status snapshot:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>In a terminal, status is formatted for reading. Redirected output is one JSON object, and <code>--json</code> selects that structured output even in a terminal. Watch continuously:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --watch</span></span></code></pre></div><p>A watch receives an update whenever the daemon&#39;s status changes - a job state change, transfer progress, a newly discovered or activated dataset, a snapshot deadline, or work entering or leaving a queue - and nothing while status stays the same. Transfer progress updates at most four times a second, and a transfer&#39;s rate is measured over the last second, so a transfer that stops moving shows a rate of zero rather than a slowly falling average.</p><p>Over a paired TCP listener, the client and the daemon each check that the other is still there while a watch or a transfer is running. A peer that vanished without closing the connection, such as a host that lost power or a network path that went away, is noticed within about 40 seconds: the watch ends with an <code>Unavailable</code> error, and the daemon releases what the call held. The local control socket needs no such check.</p><p>In a terminal, a watch shows the status view with the most recent job state changes beneath it, oldest first, under <code>RECENT TRANSITIONS</code>. The table shows only each job&#39;s latest state; the list also shows the changes that happened between two refreshes.</p><p>When watch output is redirected, or when <code>--json</code> is supplied, it becomes newline-delimited JSON. Each object carries the snapshot fields and <code>transitions</code>: every job state change since the previous object, in the order the daemon recorded it, with the same fields as an entry in <code>jobs</code> apart from transfer progress, including the <a href="#job-identity">identity</a> fields it sets. A job that changed state several times between two objects has one entry in <code>jobs</code> and one entry in <code>transitions</code> for each change. The first object, and an object sent for a change that was not a job state change, carry an empty <code>transitions</code> array.</p><p>A watch that falls too far behind the daemon, because the client or its connection cannot keep up, ends with an <code>Aborted</code> error and exits with status one rather than continuing with changes missing. Start it again to receive a fresh snapshot; changes made while no watch was connected are not replayed. A script that runs a watch unattended should treat that exit as a reason to reconnect, not as the daemon failing.</p><h3 id="job-states" tabindex="-1">Job states <a class="header-anchor" href="#job-states" aria-label="Permalink to &quot;Job states&quot;">​</a></h3><p>A job&#39;s <code>state</code> in <code>status</code>, in <code>transitions</code>, and in the <a href="#job-state-lines">job state lines</a> is one of:</p><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td><code>pending-management</code>, <code>pending-transfer</code></td><td>Queued in that worker pool, waiting for a worker</td></tr><tr><td><code>snapshotting</code></td><td>Taking a scheduled or triggered snapshot</td></tr><tr><td><code>pruning</code></td><td>Destroying snapshots that retention no longer keeps, on the source (<code>prune:</code>) or a destination (<code>destination-prune:</code>)</td></tr><tr><td><code>reconciling</code></td><td>Activating or deactivating a dataset</td></tr><tr><td><code>retiring</code></td><td>Retiring a deactivated dataset once its inactive grace period has passed</td></tr><tr><td><code>planning</code></td><td>A local transfer is planning, placing holds, and preparing its destination</td></tr><tr><td><code>probing</code></td><td>A remote transfer is connecting to its remote and planning</td></tr><tr><td><code>sending</code></td><td>A transfer stream is running; the progress fields describe it</td></tr><tr><td><code>verifying</code></td><td>The stream has finished; the daemon is verifying the result and reconciling destination properties</td></tr><tr><td><code>succeeded</code></td><td>The job finished its work</td></tr><tr><td><code>scheduled</code></td><td>The job found nothing due yet; <code>reason</code> says why</td></tr><tr><td><code>waiting-retry</code></td><td>The job will be retried later, for example after a remote was unreachable; <code>reason</code> carries the cause</td></tr><tr><td><code>blocked</code></td><td>The job stopped on a condition it cannot resolve itself; <code>reason</code> carries the cause</td></tr><tr><td><code>failed</code></td><td>The job failed; <code>reason</code> carries the error</td></tr><tr><td><code>cancelled</code></td><td>The job was stopped, or removed from its queue before it started; <code>reason</code> says why, for example <code>daemon shutting down</code>, <code>dataset deactivated</code>, or <code>remote configuration changed</code> for queued remote transfers a reload requeues against a changed remote</td></tr></tbody></table><p>A transfer that resumes an interrupted stream and then has newer state to send reports <code>sending</code> twice, once for each stream, so its byte count starting again from zero has a visible cause. A remote transfer whose destination is already up to date goes from <code>probing</code> to <code>succeeded</code> without <code>sending</code>.</p><h3 id="job-identity" tabindex="-1">Job identity <a class="header-anchor" href="#job-identity" aria-label="Permalink to &quot;Job identity&quot;">​</a></h3><p>A job name such as <code>snapshot:tank/data</code> names work that recurs. Each state change also says which run of that work it belongs to and what that run acted on, so a change can be tied to the snapshot or dataset it concerns. In JSON output an unset field is omitted; in the job state lines an unset key is left out.</p><table tabindex="0"><thead><tr><th>Field</th><th>Set on</th><th>Meaning</th></tr></thead><tbody><tr><td><code>run_id</code></td><td>Every state change of a job</td><td>The run: its pending state, start state, transfer phases, and outcome share one number. A configuration reload is a run of its own. Numbers are unique while the daemon runs and start again when it restarts.</td></tr><tr><td><code>snapshot</code></td><td><code>snapshot:</code> <code>succeeded</code></td><td>The snapshot the job created</td></tr><tr><td></td><td><code>snapshot:</code> <code>scheduled</code></td><td>The owned snapshot whose age set the next deadline</td></tr><tr><td></td><td>Transfer <code>sending</code></td><td>The source snapshot the stream sends</td></tr><tr><td></td><td>Transfer <code>succeeded</code></td><td>The snapshot now on the destination</td></tr><tr><td></td><td>Transfer <code>waiting-retry</code>, <code>blocked</code>, <code>cancelled</code></td><td>The pending snapshot the run was carrying, or, for a run that stopped before taking one, the snapshot pending when it stopped. A transfer cancelled while still queued, before it started, names none.</td></tr><tr><td><code>base</code></td><td>Transfer <code>sending</code></td><td>The snapshot or bookmark an incremental stream is based on</td></tr><tr><td><code>mode</code></td><td>Transfer <code>sending</code></td><td><code>full</code>, <code>incremental-latest</code>, <code>incremental-all</code>, or <code>resume</code></td></tr><tr><td><code>destination</code></td><td>Transfer <code>succeeded</code></td><td>The destination dataset</td></tr><tr><td><code>marker</code></td><td><code>inactive:</code> <code>succeeded</code></td><td>What reconciliation did to the inactive marker: <code>set</code>, <code>cleared</code>, or <code>none</code></td></tr><tr><td><code>destroyed</code></td><td><code>prune:</code>, <code>retire:</code> <code>succeeded</code></td><td>The snapshots destroyed, at most 64 of them</td></tr><tr><td><code>destroyed_count</code></td><td><code>prune:</code>, <code>retire:</code> <code>succeeded</code></td><td>How many snapshots were destroyed; larger than the length of <code>destroyed</code> when that list was cut</td></tr><tr><td><code>config_generation</code></td><td><code>config:reload</code> <code>succeeded</code></td><td>The configuration generation the reload published</td></tr></tbody></table><p>In a terminal, the recent transitions beneath a watch show these fields as <code>key=value</code> pairs before the reason, with <code>destroyed</code> shown as its count.</p><h2 id="request-a-snapshot" tabindex="-1">Request a snapshot <a class="header-anchor" href="#request-a-snapshot" aria-label="Permalink to &quot;Request a snapshot&quot;">​</a></h2><p>Queue an immediate snapshot for every active root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trigger</span></span></code></pre></div><p>Or name one or more active scheduling roots:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trigger</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/home</span></span></code></pre></div><p>A trigger uses the normal queue and safety checks. It does not duplicate work that is already queued or running.</p><h2 id="confirm-that-protection-is-current" tabindex="-1">Confirm that protection is current <a class="header-anchor" href="#confirm-that-protection-is-current" aria-label="Permalink to &quot;Confirm that protection is current&quot;">​</a></h2><p>Use all three views:</p><ol><li><code>boomerangz status</code> to confirm the daemon and recent work;</li><li><code>boomerangz dataset inspect DATASET</code> to confirm the effective policy;</li><li><code>zfs list -t snapshot -r DATASET</code> on the source and <code>zfs list -r ROOT</code> on each destination to confirm the stored data.</li></ol><p>For remote destinations, confirm both the most recent successful transfer and the destination dataset itself. A successful source snapshot alone does not prove that an independent copy exists.</p><h2 id="apply-configuration-changes" tabindex="-1">Apply configuration changes <a class="header-anchor" href="#apply-configuration-changes" aria-label="Permalink to &quot;Apply configuration changes&quot;">​</a></h2><p>After editing configuration files, apply them without interrupting active work:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-U1PMQ" id="tab-0ddLdhi" checked><label data-title="Linux / systemd" for="tab-0ddLdhi">Linux / systemd</label><input type="radio" name="group-U1PMQ" id="tab-KPhJgK_"><label data-title="Direct command" for="tab-KPhJgK_">Direct command</label></div><div class="blocks"><div class="language-sh vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz.service</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span></span></code></pre></div></div></div><p>The direct command&#39;s JSON result identifies fields applied live and any <code>restart_required</code> fields retained from the previous configuration. The systemd action writes the same result to the service journal. An invalid or otherwise unusable candidate leaves the running configuration unchanged and causes the reload action to fail. See <a href="/guide/configuration#validate-changes">Configure the daemon</a> for the reload contract and non-default socket usage.</p><p>A reload leaves a control listener whose configuration is unchanged in place, along with its connections. A listener using <code>mtls</code> or <code>mtls+token</code> also counts as changed when the contents of its client CA file changed, because the CA is read when the listener starts. A listener that is moved, replaced or removed stops accepting before the reload returns, and its clients&#39; existing connections start no new calls. Calls already running on it, such as replication transfers, run to completion, or until transport keepalive finds that their peer has vanished. A <code>status --watch</code> connected to it never completes, so it ends at once with an error saying the listener was retired; start it again against the current socket or endpoint.</p><p>Only restart the service when the reload result requires it, such as after changing <code>paths.identity_dir</code>, or when performing planned maintenance. Stopping the daemon prevents new work and cancels active transfers; recoverable transfer state is retained so work can continue after restart.</p><h2 id="monitor-storage" tabindex="-1">Monitor storage <a class="header-anchor" href="#monitor-storage" aria-label="Permalink to &quot;Monitor storage&quot;">​</a></h2><p>Review source snapshots and destination usage regularly:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name,used,available,refer,mountpoint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name,used,refer,creation</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> creation</span></span></code></pre></div><p>Retention limits snapshot history, but snapshots can remain because another ZFS object or an incomplete replication still depends on them. Investigate rather than deleting unfamiliar state manually.</p>`,53)])])}const u=t(n,[["render",d]]);export{g as __pageData,u as default};
